WITH latest_match AS (SELECT s.*, x.subscription_start_date, x.monthly_fee FROM customers s LEFT JOIN LATERAL (SELECT c.start_date AS subscription_start_date, c.monthly_fee FROM subscriptions c WHERE c.customer_id = s.id ORDER BY c.monthly_fee DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN age >= 61 THEN 'LARGE' ELSE 'SMALL' END AS age_tier, country, SUM(CASE WHEN country = 'SG' THEN credit_limit ELSE 0 END) AS sg_credit_limit, COUNT_IF(city = 'London') AS london_events, STDDEV_SAMP(age) AS age_stddev, PERCENTILE_APPROX(credit_limit, 0.9) AS credit_limit_p90, ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN city = 'Singapore' THEN 1 END), 0), 2) AS monthly_fee_per_singapore, SIZE(COLLECT_SET(country)) AS num_countries FROM latest_match GROUP BY age_tier, country;
